<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Holder\UserPasswordAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserPasswordAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserPasswordAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getPassword returns null on a freshly created holder.
     */
    public function testPasswordNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserPasswordAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isPasswordAssigned());
        $this->assertNull($holder->getPassword());
    }
}
class ImplWithUserPasswordAttributeHolderUnitTest
{
    use UserPasswordAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedPasswordRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultPassword();
    }
}
